  "       model:'',                                            "
  "    models:true,  nokey:true },\n  custom:      { label:'Cus"
  "tom (OpenAI-compatible)',base:'',                           "
  "                            model:'',                       "
  "                         models:true,  nokey:true }\n};\ncon"
  "st AI_EXAMPLES = [\n  'light 1st 8 leds in red, next 8 in bl"
  "ue',\n  'blink 1-4 leds in red with 1 seconds delay, blink r"
  "est in yellow with 3 seconds delay',\n  'light 1st 6 leds wi"
  "th red, next 4 in yellow, last 6 in red'\n];\nconst AI_CORS_"
  "HINT = 'If this is a CORS/network error, the provider blocks"
  " direct browser calls - ' +\n  'OpenAI, DeepInfra, OpenRoute"
  "r, Groq, Mistral, Together, Cerebras, Gemini and local Ollam"
  "a/LM Studio are known to work.';\n\nfunction aiLoadCfg(){\n "
  " try { return JSON.parse(localStorage.getItem('nps-ai')) || "
  "{}; } catch(err){ return {}; }\n}\nfunction aiSaveCfg(){ try"
  "{ localStorage.setItem('nps-ai', JSON.stringify(AI_CFG)); }c"
  "atch(err){} }\nconst AI_CFG = aiLoadCfg();\nAI_CFG.keys = AI"
  "_CFG.keys || {}; AI_CFG.models = AI_CFG.models || {}; AI_CFG"
  ".bases = AI_CFG.bases || {};\nif (!AI_CFG.provider) AI_CFG.p"
  "rovider = 'deepinfra';\n\nlet aiHistory = [];          // [{"
  "role:'user'|'assistant', content}]\nlet aiBusy = false;\n\nf"
  "unction aiEffective(){\n  const p = AI_PROVIDERS[AI_CFG.prov"
  "ider] || AI_PROVIDERS.deepinfra;\n  return {\n    id: AI_CFG"
  ".provider, p,\n    base: (AI_CFG.bases[AI_CFG.provider] || p"
  ".base || '').replace(/\\/+$/,''),\n    model: AI_CFG.models["
  "AI_CFG.provider] || p.model || '',\n    key: AI_CFG.keys[AI_"
  "CFG.provider] || ''\n  };\n}\nfunction aiConfigured(){\n  co"
  "nst e = aiEffective();\n  return !!e.base && !!e.model && (!"
  "!e.key || e.p.nokey);\n}\nfunction aiUpdateTag(){\n  const t"
  " = $('#aiProvTag'); if (!t) return;\n  if (!aiConfigured()){"
  " t.textContent = 'not configured'; t.className = 'tag'; retu"
  "rn; }\n  const e = aiEffective();\n  t.textContent = e.p.lab"
  "el + ' \\u00b7 ' + e.model;\n  t.className = 'tag c';\n}\n\n"
  "/* ------------------------------ the prompt ---------------"
  "---------------- */\nfunction aiSystemPrompt(){\n  const n ="
  " S.leds;\n  return 'You are the show planner inside NeoPixel"
  " Studio, a controller for a strip of ' + n +\n    ' WS2812B "
  "LEDs, indexed 0..' + (n-1) + '. The user describes a light s"
  "how in plain language. ' +\n    'Reply with ONE JSON object "
  "and NOTHING else - no markdown, no code fences.\\n' +\n    '"
  "Schema:\\n' +\n    '{\"reply\":\"1-3 short friendly sentence"
  "s (what you built, or the answer)\",\"brightness\":0-255(opt"
  "ional),' +\n    '\"globalSpeed\":0.1-4.0(optional),\"layers"
  "\":[{\"kind\":\"solid\",\"c1\":\"#rrggbb\",\"start\":0,\"end"
  "\":7},\\n' +\n    '{\"kind\":\"effect\",\"effect\":\"<name>"
  "\",\"c1\":\"#rrggbb\",\"c2\":\"#rrggbb\",\"start\":0,\"end\""
  ":' + (n-1) + ',\"speed\":1.0,\"bpm\":30,\"blend\":\"over\"},"
  "\\n' +\n    '{\"kind\":\"pixels\",\"colors\":[\"#rrggbb\",.."
  ".one per LED in range],\"start\":0,\"end\":' + (n-1) + '}]}"
  "\\n' +\n    'Effects (use these exact names): Solid, Blink, "
  "Breathe, Rainbow, Rainbow cycle, Chase, Comet, ' +\n    'The"
  "atre chase, Colour wipe, Sparkle, Fire, Gradient, Dual scan,"
  " Strobe, Meteor shower, Colour fade.\\n' +\n    'Timing: Bli"
  "nk full on/off period = 30/bpm seconds (bpm 30 = 1 s, bpm 10"
  " = 3 s, bpm 60 = 0.5 s; on half the time). ' +\n    'Strobe "
  "flash \\u2248 0.12*(60/bpm) s. Breathe period = 60/bpm s. Co"
  "lour wipe fill cycle = 60/bpm s. ' +\n    'Colour fade c1<->"
  "c2 cycle = 120/bpm s. speed multiplies motion tempo (1.0 = n"
  "ormal; keep 1.0 when the user ' +\n    'names an exact delay"
  ", so bpm alone sets the timing). Omit bpm for effects that d"
  "o not need it.\\n' +\n    'Rules: ranges are 0-based and INC"
  "LUSIVE; use one layer per LED group; ranges must stay within"
  " 0..' + (n-1) + '. ' +\n    'Layers composite top-down: a la"
  "ter layer overwrites earlier ones where they overlap, unless"
  " blend is ' +\n    '\"add\" or \"screen\" (glows on top of w"
  "hat is below) or \"multiply\" (darkens). ' +\n    '\"pixels"
  "\" paints exact per-LED colours - best for fixed multi-colou"
  "r patterns (alternating colours, stripes); ' +\n    'if colo"
  "rs has fewer entries than the range, it repeats. c2 is the s"
  "econdary/background colour (black = off). ' +\n    'When the"
  " user groups LEDs (\"first 8\", \"middle\", \"last 6\"), tra"
  "nslate that to indexes. ' +\n    'If the user asks a questio"
  "n or just chats, answer in \"reply\" and omit \"layers\". ' "
  "+\n    'Include \"brightness\" ONLY when the user names a br"
  "ightness level or percentage (\"half brightness\", \"at 80%"
  "\"): ' +\n    'a percentage p maps to Math.round(p*2.55). Ot"
  "herwise omit it - the studio applies a 25% default. ' +\n   "
  " 'Never wrap the JSON in backticks.';\n}\n\n/* -------------"
  "-------------- provider adapters ---------------------------"
  " */\nfunction aiAuthHeaders(e, json){\n  const h = { 'Conten"
  "t-Type':'application/json' };\n  if (e.p.kind === 'anthropic"
  "'){\n    h['x-api-key'] = e.key;\n    h['anthropic-version']"
  " = '2023-06-01';\n    h['anthropic-dangerous-direct-browser-"
  "access'] = 'true';\n  } else if (e.p.kind === 'azure'){\n   "
  " h['api-key'] = e.key;\n  } else if (e.key){\n    h['Authori"
  "zation'] = 'Bearer ' + e.key;\n  }\n  if (e.id === 'openrout"
  "er'){ h['X-Title'] = 'NeoPixel Studio'; }\n  return h;\n}\na"
  "sync function aiFetchJson(e, path, opts, timeoutMs){\n  cons"
  "t ctl = new AbortController();\n  const timer = setTimeout(("
  ")=>ctl.abort(), timeoutMs || 90000);\n  try {\n    const res"
  " = await fetch(e.base + path, Object.assign({ signal: ctl.si"
  "gnal }, opts));\n    const txt = await res.text();\n    if ("
  "!res.ok){\n      let msg = 'HTTP ' + res.status;\n      try "
  "{ const j = JSON.parse(txt); msg += ': ' + (j.error && (j.er"
  "ror.message || j.error.type) || JSON.stringify(j.error) || J"
  "SON.stringify(j)).slice(0,300); }\n      catch(err){ msg += "
  "': ' + txt.slice(0,300); }\n      throw new Error(msg);\n   "
  " }\n    return JSON.parse(txt);\n  } finally { clearTimeout("
  "timer); }\n}\n/* Sends the conversation; returns the assista"
  "nt text. */\nasync function aiChat(e, sysText){\n  const msg"
  "s = [{ role:'system', content: sysText }, ...aiHistory];\n  "
  "let text;\n  if (e.p.kind === 'anthropic'){\n    const body "
  "= { model: e.model, max_tokens: 1024, system: sysText,\n    "
  "               messages: aiHistory.map(m=>({ role:m.role, co"
  "ntent:m.content })) };\n    const j = await aiFetchJson(e, '"
  "/v1/messages', { method:'POST', headers: aiAuthHeaders(e), b"
  "ody: JSON.stringify(body) });\n    text = (j.content||[]).fi"
  "lter(b=>b.type==='text').map(b=>b.text).join('\\n');\n  } el"
  "se {\n    const body = { model: e.model, messages: msgs, tem"
  "perature: 0.2, max_tokens: 1024, stream: false };\n    const"
  " j = await aiFetchJson(e, '/chat/completions', { method:'POS"
  "T', headers: aiAuthHeaders(e), body: JSON.stringify(body) })"
  ";\n    const ch = j.choices && j.choices[0];\n    text = (ch"
  " && ch.message && ch.message.content) || (ch && ch.text) || "
  "'';\n  }\n  return String(text||'').trim();\n}\nasync functi"
  "on aiListModels(){\n  const e = aiEffective();\n  if (!e.p.m"
  "odels) throw new Error('this provider has no model list - ty"
  "pe the model name');\n  if (!e.base) throw new Error('set th"
  "e base URL first');\n  let j;\n  if (e.p.kind === 'anthropic"
  "'){\n    j = await aiFetchJson(e, '/v1/models', { headers: a"
  "iAuthHeaders(e) }, 20000);\n  } else {\n    j = await aiFetc"
  "hJson(e, '/models', { headers: aiAuthHeaders(e) }, 20000);\n"
  "  }\n  const arr = (j.data || j.models || []).map(m => m.id "
  "|| m.name || '').filter(Boolean);\n  arr.sort();\n  return a"
  "rr;\n}\n\n/* ---------------------- plan -> layers -> apply "
  "-------------------------- */\nfunction aiResolveEffect(name"
  "){\n  const want = String(name||'').toLowerCase().replace(/["
  "^a-z0-9]/g,'');\n  const alias = { solid:'Solid', blink:'Bli"
  "nk', breathe:'Breathe', rainbow:'Rainbow',\n    rainbowcycle"
  ":'Rainbow cycle', cycle:'Rainbow cycle', chase:'Chase', come"
  "t:'Comet',\n    theatre:'Theatre chase', theater:'Theatre ch"
  "ase', theatrechase:'Theatre chase',\n    colorwipe:'Colour w"
  "ipe', colourwipe:'Colour wipe', wipe:'Colour wipe',\n    spa"
  "rkle:'Sparkle', fire:'Fire', gradient:'Gradient', dualscan:'"
  "Dual scan',\n    strobe:'Strobe', meteor:'Meteor shower', me"
  "teorshower:'Meteor shower',\n    colorfade:'Colour fade', co"
  "lourfade:'Colour fade', fade:'Colour fade' };\n  if (alias[w"
  "ant]) return alias[want];\n  for (const n of FX){ if (n.toLo"
  "werCase().replace(/[^a-z0-9]/g,'') === want) return n; }\n  "
  "return null;\n}\nfunction aiBlendIdx(b){\n  const i = BLENDS"
  ".indexOf(String(b||'over').toLowerCase());\n  return i < 0 "
  "\? 0 : i;\n}\nfunction layerFromAiSpec(spec){\n  if (!spec |"
  "| typeof spec !== 'object') return null;\n  const start = cl"
  "amp(Math.round(+spec.start || 0), 0, S.leds-1);\n  const end"
  "   = clamp(Math.round(spec.end != null \? +spec.end : S.leds"
  "-1), 0, S.leds-1);\n  const c1 = parseHex(spec.c1 || '#ff000"
  "0');\n  const c2 = parseHex(spec.c2 || '#000000');\n  const "
  "speedQ = clamp(Math.round((+spec.speed || 1) * 10), 1, 40);"
  "\n  const bpmQ   = clamp(Math.round((+spec.bpm || 60) / 10),"
  " 1, 255);\n  const blend  = aiBlendIdx(spec.blend);\n  const"
  " kind = String(spec.kind || 'effect').toLowerCase();\n\n  if"
  " (kind === 'solid'){\n    return mkSolid(c1, start, end, { b"
  "lend });\n  }\n  if (kind === 'pixels' || Array.isArray(spec"
  ".colors)){\n    const L = mkPixels({ start, end, blend });\n"
  "    let cols = (spec.colors || [spec.c1]).map(x => Array.isA"
  "rray(x) \? x.map(clamp255) : parseHex(x))\n                ."
  "filter(c => c && (c[0]||c[1]||c[2]));\n    if (!cols.length)"
  " cols = [c1];\n    for (let i = start; i <= end; i++){\n    "
  "  const c = cols[(i - start) % cols.length];\n      L.pixels"
  "[i*3] = c[0]; L.pixels[i*3+1] = c[1]; L.pixels[i*3+2] = c[2]"
  ";\n    }\n    return L;\n  }\n  const name = aiResolveEffect"
  "(spec.effect);\n  if (!name) return null;\n  return mkEffect"
  "(name, start, end, { c1, c2, speedQ, bpmQ, blend });\n}\nfun"
  "ction aiCloneLayers(){\n  return S.layers.map(L=>{\n    cons"
  "t cp = JSON.parse(JSON.stringify(L, (k,v)=> v instanceof Uin"
  "t8Array \? Array.from(v) : v));\n    if (cp.pixels) cp.pixel"
  "s = Uint8Array.from(cp.pixels);\n    return cp;\n  });\n}\n/"
  "* Applies the plan the same way the Simple-mode buttons do: "
  "replaces the\n   stack, drops any recorded show, mirrors pix"
  "el layers into S.px.\n   Multiple \"pixels\" specs merge int"
  "o ONE pixel layer because the device\n   protocol ('l' blob)"
  " carries pixel data for a single pixel layer. */\nfunction a"
  "pplyAiPlan(plan){\n  const layers = [];\n  let pxLayer = nul"
  "l;                 // merged pixel layer, placed at first sp"
  "ec\n  for (const spec of (plan.layers||[])){\n    if (layers"
  ".length >= MAX_LAYERS) break;\n    const kind = String((spec"
  " && spec.kind) || 'effect').toLowerCase();\n    const isPixe"
  "ls = kind === 'pixels' || Array.isArray(spec && spec.colors)"
  ";\n    if (isPixels){\n      if (!pxLayer){ pxLayer = mkPixe"
  "ls(); layers.push(pxLayer); }\n      const start = clamp(Mat"
  "h.round(+(spec.start||0)), 0, S.leds-1);\n      const end   "
  "= clamp(Math.round(spec.end != null \? +spec.end : S.leds-1)"
  ", 0, S.leds-1);\n      let cols = (spec.colors || [spec.c1])"
  ".map(x => Array.isArray(x) \? x.map(clamp255) : parseHex(x))"
  "\n                  .filter(c => c && (c[0]||c[1]||c[2]));\n"
  "      if (!cols.length) cols = [parseHex(spec.c1 || '#ff0000"
  "')];\n      for (let i = start; i <= end; i++){\n        con"
  "st c = cols[(i - start) % cols.length];\n        pxLayer.sta"
  "rt = Math.min(pxLayer.start, start);\n        pxLayer.end   "
  "= Math.max(pxLayer.end, end);\n        pxLayer.pixels[i*3] ="
  " c[0]; pxLayer.pixels[i*3+1] = c[1]; pxLayer.pixels[i*3+2] ="
  " c[2];\n      }\n      continue;\n    }\n    const L = layer"
  "FromAiSpec(spec);\n    if (L) layers.push(L);\n  }\n  if (!l"
  "ayers.length) return null;\n  const snap = { layers: aiClone"
  "Layers(), px: S.px.map(c=>c.slice()), selLayer: S.selLayer,"
  "\n                 brightness: S.brightness, gspdQ: S.gspdQ "
  "};\n  S.layers = layers; S.selLayer = 0;\n  S.playing = true"
  ";\n  S.curStep = -1; stepIdx = -1; stepAccum = 0;\n  if (S.s"
  "treaming) setStream(false);\n  wsSend('t', new Uint8Array([0"
  ",0,0])); markTimeline();\n  if (plan.brightness != null && i"
  "sFinite(+plan.brightness)){\n    S.brightness = clamp(Math.r"
  "ound(+plan.brightness), 0, 255);\n  } else {\n    S.brightne"
  "ss = 64;    // 25% of 255: AI effects land easy on the eyes "
  "unless the user names a level\n  }\n  $('#rBright').value = "
  "S.brightness; $('#vBright').textContent = S.brightness;\n  $"
  "('#rSimBright').value = S.brightness; $('#vSimBright').textC"
  "ontent = S.brightness;\n  if (plan.globalSpeed != null && is"
  "Finite(+plan.globalSpeed)){\n    S.gspdQ = clamp(Math.round("
  "+plan.globalSpeed * 10), 1, 40);\n    $('#rGspd').value = S."
  "gspdQ; $('#vGspd').textContent = (S.gspdQ/10).toFixed(2)+'\\"
  "u00d7';\n    $('#rSimSpd').value = S.gspdQ; $('#vSimSpd').te"
  "xtContent = (S.gspdQ/10).toFixed(1)+'\\u00d7';\n  }\n  const"
  " px = layers.find(l=>l.type==='pixels');\n  if (px){ for (le"
  "t i=0;i<S.leds;i++) S.px[i] = [px.pixels[i*3], px.pixels[i*3"
  "+1], px.pixels[i*3+2]]; }\n  renderLayers(); buildGrid(); pu"
  "shGlobals(); push();\n  return snap;\n}\nfunction aiDescribe"
  "Layers(layers){\n  return layers.map(L=>{\n    const what = "
  "(L.type==='solid') \? 'Solid ' + toHex(L.c1)\n              "
  " : (L.type==='pixels') \? 'Pixel colours'\n               : "
  "FX[L.effect] + ' ' + toHex(L.c1);\n    return what + ' \\u00"
  "b7 LEDs ' + L.start + '-' + L.end;\n  });\n}\n/* Pulls the f"
  "irst JSON object out of a reply (models love to chat around "
  "it). */\nfunction aiExtractJson(text){\n  const t = text.rep"
  "lace(/```(\?:json)\?/gi, '').trim();\n  const a = t.indexOf("
  "'{'), b = t.lastIndexOf('}');\n  if (a < 0 || b <= a) return"
  " null;\n  try { return JSON.parse(t.slice(a, b+1)); } catch("
  "err){ return null; }\n}\n\n/* ------------------------------"
  "- chat UI --------------------------------- */\nfunction aiA"
  "ddMsg(cls, text){\n  const host = $('#aiLog');\n  const d = "
  "document.createElement('div');\n  d.className = 'msg ' + cls"
  ";\n  if (text) d.textContent = text;\n  host.appendChild(d);"
  "\n  host.scrollTop = host.scrollHeight;\n  return d;\n}\nfun"
  "ction aiErrText(err){\n  if (err && err.name === 'AbortError"
  "') return 'Timed out waiting for the AI (90 s). Try again, o"
  "r pick a faster model.';\n  if (err instanceof TypeError) re"
  "turn 'Network or CORS error: ' + (err.message||'request bloc"
  "ked') + '. ' + AI_CORS_HINT;\n  return (err && err.message) "
  "\? err.message : String(err);\n}\nfunction aiHandleReply(raw"
  "){\n  aiHistory.push({ role:'assistant', content: raw });\n "
  " if (aiHistory.length > 12) aiHistory = aiHistory.slice(-12)"
  ";\n  const plan = aiExtractJson(raw);\n  const d = aiAddMsg("
  "'ai', '');\n  if (plan && (plan.layers || plan.reply != null"
  ")){\n    d.textContent = String(plan.reply || 'Here you go!'"
  ").trim() || 'Here you go!';\n    if (plan.layers && plan.lay"
  "ers.length){\n      const snap = applyAiPlan(plan);\n      i"
  "f (snap){\n        const box = document.createElement('div')"
  "; box.className = 'applied';\n        const t = document.cre"
  "ateElement('span');\n        t.className = 'tag g';\n       "
  " t.textContent = 'applied ' + S.layers.length + ' layer' + ("
  "S.layers.length>1\?'s':'') + ': ' +\n                       "
  " aiDescribeLayers(S.layers).join('  |  ');\n        const un"
  "do = document.createElement('button');\n        undo.classNa"
  "me = 'btn sm';\n        undo.textContent = 'Undo';\n        "
  "undo.onclick = ()=>{\n          S.layers = snap.layers; S.se"
  "lLayer = snap.selLayer;\n          S.px = snap.px.map(c=>c.s"
  "lice());\n          S.brightness = snap.brightness; S.gspdQ "
  "= snap.gspdQ;\n          $('#rBright').value = S.brightness;"
  " $('#vBright').textContent = S.brightness;\n          $('#rS"
  "imBright').value = S.brightness; $('#vSimBright').textConten"
  "t = S.brightness;\n          $('#rGspd').value = S.gspdQ; $("
  "'#vGspd').textContent = (S.gspdQ/10).toFixed(2)+'\\u00d7';\n"
  "          $('#rSimSpd').value = S.gspdQ; $('#vSimSpd').textC"
  "ontent = (S.gspdQ/10).toFixed(1)+'\\u00d7';\n          rende"
  "rLayers(); buildGrid(); pushGlobals(); push();\n          un"
  "do.disabled = true; undo.textContent = 'undone';\n        };"
  "\n        box.append(t, undo);\n        d.appendChild(box);"
  "\n      } else {\n        d.appendChild(Object.assign(docume"
  "nt.createElement('div'),\n          { className:'hint', text"
  "Content:'I could not turn that into layers - try rephrasing."
  "' }));\n      }\n    }\n  } else {\n    d.textContent = raw "
  "|| '(empty reply)';\n  }\n  const host = $('#aiLog'); host.s"
  "crollTop = host.scrollHeight;\n}\nasync function aiSend(text"
  "){\n  text = String(text||'').trim();\n  if (!text || aiBusy"
  ") return;\n  if (!aiConfigured()){\n    aiAddMsg('err', 'Pic"
  "k a provider, model and API key in AI settings first (works "
  "with DeepInfra, OpenAI, Claude, Gemini, Groq, OpenRouter, lo"
  "cal Ollama and more).');\n    aiOpenSettings();\n    return;"
  "\n  }\n  aiBusy = true; $('#btnAiSend').disabled = true;\n  "
  "aiAddMsg('user', text);\n  aiHistory.push({ role:'user', con"
  "tent: text });\n  if (aiHistory.length > 12) aiHistory = aiH"
  "istory.slice(-12);\n  const typing = aiAddMsg('ai', '');\n  "
  "typing.innerHTML = '<span class=\"typing\"><i></i><i></i><i>"
  "</i></span>';\n  try {\n    const reply = await aiChat(aiEff"
  "ective(), aiSystemPrompt());\n    typing.remove();\n    aiHa"
  "ndleReply(reply);\n  } catch(err){\n    typing.remove();\n  "
  "  aiAddMsg('err', aiErrText(err));\n  }\n  aiBusy = false; $"
  "('#btnAiSend').disabled = false;\n  const host = $('#aiLog')"
  "; host.scrollTop = host.scrollHeight;\n}\n\n/* -------------"
  "-------------- settings modal ------------------------------"
  " */\nfunction aiFillProviderSelect(){\n  const sel = $('#aiP"
  "rovider'); sel.innerHTML = '';\n  for (const [id,p] of Objec"
  "t.entries(AI_PROVIDERS)){\n    const o = document.createElem"
  "ent('option'); o.value = id; o.textContent = p.label;\n    s"
  "el.appendChild(o);\n  }\n  sel.value = AI_CFG.provider;\n}\n"
  "function aiLoadSettingsForm(){\n  const e = aiEffective();\n"
  "  $('#aiProvider').value = AI_CFG.provider;\n  $('#aiModel')"
  ".value = e.model;\n  $('#aiKey').value = e.key;\n  $('#aiBas"
  "eUrl').value = e.base;\n  $('#aiProvHint').textContent = e.p"
  ".nokey\n    \? 'No API key needed for this provider.'\n    :"
  " 'Default model: ' + (e.p.model || '(type one)') + '. \"Load"
  "\" fetches the live model list from the provider.';\n}\nfunc"
  "tion aiStashForm(){\n  const id = AI_CFG.provider;\n  AI_CFG"
  ".models[id] = $('#aiModel').value.trim();\n  AI_CFG.keys[id]"
  "   = $('#aiKey').value.trim();\n  AI_CFG.bases[id]  = $('#ai"
  "BaseUrl').value.trim();\n}\nfunction aiOpenSettings(){ aiLoa"
  "dSettingsForm(); $('#aiModal').classList.add('on'); $('#aiKe"
  "y').focus(); }\nfunction aiCloseSettings(){ aiStashForm(); a"
  "iSaveCfg(); aiUpdateTag(); $('#aiModal').classList.remove('o"
  "n'); }\n\n/* -------------------------------- init ---------"
  "-------------------------- */\n(function aiInit(){\n  const "
  "host = $('#aiExamples'); if (!host) return;\n  AI_EXAMPLES.f"
  "orEach(x=>{\n    const c = document.createElement('button');"
  "\n    c.className = 'chip'; c.textContent = x;\n    c.title "
  "= x;\n    c.onclick = ()=>{ $('#aiInput').value = x; $('#aiI"
  "nput').focus(); };\n    host.appendChild(c);\n  });\n  aiFil"
  "lProviderSelect();\n  aiUpdateTag();\n\n  $('#btnAiSend').on"
  "click = ()=>{ const v = $('#aiInput').value; $('#aiInput').v"
  "alue=''; aiSend(v); };\n  $('#aiInput').addEventListener('ke"
  "ydown', e=>{\n    if (e.key === 'Enter' && !e.isComposing){ "
  "e.preventDefault(); const v = $('#aiInput').value; $('#aiInp"
  "ut').value=''; aiSend(v); }\n  });\n  $('#btnAiClear').oncli"
  "ck = ()=>{ aiHistory = []; $('#aiLog').innerHTML = ''; };\n "
  " $('#btnAiSettings').onclick = aiOpenSettings;\n  $('#btnAiS"
  "ave').onclick = aiCloseSettings;\n  $('#btnAiClose').onclick"
  " = aiCloseSettings;\n  $('#aiModal').addEventListener('click"
  "', e=>{ if (e.target === $('#aiModal')) aiCloseSettings(); }"
  ");\n  $('#aiProvider').onchange = ()=>{ aiStashForm(); AI_CF"
  "G.provider = $('#aiProvider').value; aiLoadSettingsForm(); }"
  ";\n  $('#aiModel').onchange   = ()=>aiStashForm();\n  $('#ai"
  "Key').onchange     = ()=>aiStashForm();\n  $('#aiBaseUrl').o"
  "nchange = ()=>aiStashForm();\n  $('#btnAiModels').onclick = "
  "async ()=>{\n    const btn = $('#btnAiModels'), hint = $('#a"
  "iProvHint');\n    aiStashForm();\n    btn.disabled = true; c"
  "onst old = btn.textContent; btn.textContent = '...';\n    tr"
  "y {\n      const ids = await aiListModels();\n      const dl"
  " = $('#aiModelList'); dl.innerHTML = '';\n      const cur = "
  "$('#aiModel').value;\n      for (const id of ids.slice(0, 50"
  "0)){\n        const o = document.createElement('option'); o."
  "value = id; dl.appendChild(o);\n      }\n      if (cur && !i"
  "ds.includes(cur)){\n        const o = document.createElement"
  "('option'); o.value = cur; dl.appendChild(o);\n      }\n    "
  "  hint.textContent = 'loaded ' + ids.length + ' models - cli"
  "ck the model field to pick one';\n    } catch(err){\n      h"
  "int.textContent = 'could not list models (' + aiErrText(err)"
  " + ') - just type the model name';\n    }\n    btn.disabled "
  "= false; btn.textContent = old;\n  };\n\n  if (!aiConfigured"
  "()){\n    aiAddMsg('ai', 'Hi! Tell me what the LEDs should d"
  "o and I will build the show - for example \"light 1st 8 leds"
  " in red, next 8 in blue\". ' +\n      'First, pick a provide"
  "r and paste your API key in AI settings (DeepInfra, OpenAI, "
  "Claude, Gemini, Groq, OpenRouter, local Ollama and many more"
  ").');\n  }\n})();\n\n\n/* -------------------------------- b"
  "oot ---------------------------------- */\n/* When the page "
  "is served BY the board, its own address is the only sensible"
  "\n   WebSocket endpoint, so connect without making the user "
  "press anything. That\n   also means a connection problem sho"
  "ws up immediately instead of looking like\n   an idle UI. */"
  "\nconst auto = wsUrlAuto();\n$('#wsUrl').value = auto || wsU"
  "rlDefault();\nfillFxSelect(); buildFxChips();\nbuildStrip();"
  " buildGrid(); syncSel();\ndefaultStack();\nrenderLayers(); r"
  "enderTimeline();\nbindUI();\n$('#btnMaster').classList.add('"
  "on');\n$('#mon').innerHTML = '';\nlog('sy','NeoPixel Studio "
  "ready - 16 px on GPIO4');\nlog('sy','preview runs locally at"
  " 25 fps');\n\nif (auto){\n  log('sy','auto-connecting to ' +"
  " auto + ' (served by the board)');\n  setTimeout(connect, 60"
  ");\n} else {\n  log('sy','opened from a file or a dev server"
  " - press Connect and enter ws://<board-ip>:' + WS_PORT + '/'"
  ");\n  log('sy','on the board, the Serial Monitor prints the "
  "exact WebSocket URL');\n}\n\n</script>\n</body>\n";
